#define MAXN 4
#define FACES 6
#define ORI 24

/* face indices:
   0 = up
   1 = down
   2 = front
   3 = back
   4 = left
   5 = right
*/

int n;
int cubes[MAXN][FACES];
int perms[ORI][FACES];
int permCount = 0;

void compose(int a[FACES], int b[FACES], int out[FACES]) {
    /* apply a then b: out[i] = a[b[i]] */
    for (int i = 0; i < FACES; i++) out[i] = a[b[i]];
}

int equal_perm(int a[FACES], int b[FACES]) {
    for (int i = 0; i < FACES; i++) if (a[i] != b[i]) return 0;
    return 1;
}

void generate_orientations() {
    int rx[FACES] = {3, 2, 0, 1, 4, 5}; /* rotate around x-axis */
    int ry[FACES] = {4, 5, 2, 3, 1, 0}; /* rotate around y-axis */
    int rz[FACES] = {0, 1, 5, 4, 2, 3}; /* rotate around z-axis */

    int queue[100][FACES];
    int head = 0, tail = 0;

    int id[FACES] = {0, 1, 2, 3, 4, 5};
    for (int i = 0; i < FACES; i++) queue[tail][i] = id[i];
    tail++;

    permCount = 0;

    while (head < tail) {
        int cur[FACES];
        for (int i = 0; i < FACES; i++) cur[i] = queue[head][i];
        head++;

        int exists = 0;
        for (int i = 0; i < permCount; i++) {
            if (equal_perm(perms[i], cur)) {
                exists = 1;
                break;
            }
        }
        if (exists) continue;

        for (int i = 0; i < FACES; i++) perms[permCount][i] = cur[i];
        permCount++;

        int next[FACES];

        compose(cur, rx, next);
        for (int i = 0; i < FACES; i++) queue[tail][i] = next[i];
        tail++;

        compose(cur, ry, next);
        for (int i = 0; i < FACES; i++) queue[tail][i] = next[i];
        tail++;

        compose(cur, rz, next);
        for (int i = 0; i < FACES; i++) queue[tail][i] = next[i];
        tail++;
    }
}

int best;

void dfs(int idx, int chosen[][FACES]) {
    if (idx == n) {
        int changes = 0;
        for (int f = 0; f < FACES; f++) {
            int cnt[101] = {0};
