public class Main {
    static final int[][] ROTATIONS = {
        {0,1,2,3,4,5}, {0,2,4,1,3,5}, {0,4,3,2,1,5}, {0,3,1,4,2,5},
        {1,5,2,0,4,3}, {1,2,4,5,0,3}, {1,4,3,2,5,0}, {1,3,0,4,2,5},
        {2,1,5,3,0,4}, {2,5,4,1,3,0}, {2,4,0,5,3,1}, {2,0,3,4,5,1},
        {3,0,2,5,4,1}, {3,2,4,0,5,1}, {3,4,5,2,0,1}, {3,5,1,4,0,2},
        {4,0,1,3,5,2}, {4,1,5,0,3,2}, {4,5,3,1,0,2}, {4,3,0,5,1,2},
        {5,1,0,3,4,2}, {5,0,4,1,3,2}, {5,4,3,0,1,2}, {5,3,1,4,0,2}
    };

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNext()) {
            int n = sc.nextInt();
            if (n == 0) break;
            sc.nextLine();
            List<String[]> cubes = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                String[] faces = sc.nextLine().trim().split(" ");
                cubes.add(faces);
            }
            System.out.println(minRepaint(cubes));
        }
        sc.close();
    }

    static int minRepaint(List<String[]> cubes) {
        int n = cubes.size();
        if (n == 0) return 0;
        int minChanges = Integer.MAX_VALUE;

        // Try each cube as reference orientation
        for (int refIdx = 0; refIdx < n; refIdx++) {
            String[] ref = cubes.get(refIdx);
            for (int[] rotRef : ROTATIONS) {
                String[] orientedRef = applyRotation(ref, rotRef);
                // For each possible target coloring based on this reference
                int[][] assignments = new int[n][6];
                assignments[refIdx] = rotRef;
                minChanges = Math.min(minChanges, 
                    computeMinForReference(cubes, orientedRef, refIdx, assignments));
            }
        }
        return minChanges;
    }

    static int computeMinForReference(List<String[]> cubes, String[] target, 
                                       int refIdx, int[][] assignments) {
        int n = cubes.size();
        int totalChanges = 0;
        for (int i = 0; i < n; i++) {
            if (i == refIdx) continue;
            int best = Integer.MAX_VALUE;
            for (int[] rot : ROTATIONS) {
                String[] rotated = applyRotation(cubes.get(i), rot);
                int changes = 0;
                for (int f = 0; f < 6; f++) {
                    if (!rotated[f].equals(target[f])) changes++;
                }
                if (changes < best) {
                    best = changes;
                }
            }
            totalChanges += best;
            if (totalChanges >= Integer.MAX_VALUE / 2) break;
        }
        return totalChanges;
    }

    static String[] applyRotation(String[] faces, int[] rot) {
        String[] result = new String[6];
        for (int i = 0; i < 6; i++) {
            result[i] = faces[rot[i]];
        }
        return result;
    }
}

