public class Main {
    static final int[][] PERMS = generateRotations();

    static int[][][] cubes;
    static int n;
    static int best;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            Integer ni = fs.nextIntNullable();
            if (ni == null) break;
            n = ni;
            if (n == 0) break;

            cubes = new int[n][6][];
            for (int i = 0; i < n; i++) {
                for (int f = 0; f < 6; f++) {
                    String s = fs.next();
                    cubes[i][f] = new int[]{colorId(s)};
                }
            }

            // flatten stored colors
            int[][] cubeColors = new int[n][6];
            for (int i = 0; i < n; i++) {
                for (int f = 0; f < 6; f++) cubeColors[i][f] = cubes[i][f][0];
            }

            best = Integer.MAX_VALUE;
            int[] chosen = new int[n];
            dfs(0, chosen, cubeColors);

            out.append(best).append('\n');
        }

        System.out.print(out.toString());
    }

    static void dfs(int idx, int[] chosen, int[][] cubeColors) {
        if (idx == n) {
            int repaint = 0;
            for (int face = 0; face < 6; face++) {
                HashMap<Integer, Integer> freq = new HashMap<>();
                int max = 0;
                for (int i = 0; i < n; i++) {
                    int c = cubeColors[i][PERMS[chosen[i]][face]];
                    int v = freq.getOrDefault(c, 0) + 1;
                    freq.put(c, v);
                    if (v > max) max = v;
                }
                repaint += n - max;
            }
            best = Math.min(best, repaint);
            return;
        }

        // small pruning: partial lower bound is 0, so only trivial pruning possible
        for (int r = 0; r < 24; r++) {
            chosen[idx] = r;
            dfs(idx + 1, chosen, cubeColors);
        }
    }

    // Faces order in input/output handling:
    // 0=front, 1=back, 2=left, 3=right, 4=top, 5=bottom
    //
    // A rotation permutation p means:
    // after rotation, canonical face f gets original face p[f]
    static int[][] generateRotations() {
        int[][] dirs = {
                {0, 0, 1},   // front
                {0, 0, -1},  // back
                {-1, 0, 0},  // left
                {1, 0, 0},   // right
                {0, 1, 0},   // top
                {0, -1, 0}   // bottom
        };

        ArrayList<int[]> list = new ArrayList<>();
        HashSet<String> seen = new HashSet<>();

        for (int top = 0; top < 6; top++) {
            for (int front = 0; front < 6; front++) {
                if (front == top || front == opposite(top)) continue;
                int[] y = dirs[top];
                int[] z = dirs[front];
                int[] x = cross(y, z);
                if (isZero(x)) continue;

                int[] perm = new int[6];
                for (int i = 0; i < 6; i++) {
                    int[] d = dirs[i];
                    if (eq(d, z)) perm[0] = i;          // front
                    else if (eq(d, neg(z))) perm[1] = i; // back
                    else if (eq(d, neg(x))) perm[2] = i; // left
                    else if (eq(d, x)) perm[3] = i;      // right
                    else if (eq(d, y)) perm[4] = i;      // top
                    else if (eq(d, neg(y))) perm[5] = i; // bottom
                }
                String key = Arrays.toString(perm);
                if (seen.add(key)) list.add(perm);
            }
        }

        int[][] res = new int[list.size()][6];
        for (int i = 0; i < list.size(); i++) res[i] = list.get(i);
        return res;
    }

    static int opposite(int f) {
        switch (f) {
            case 0: return 1;
            case 1: return 0;
            case 2: return 3;
            case 3: return 2;
            case 4: return 5;
            default: return 4;
        }
    }

    static int[] cross(int[] a, int[] b) {
        return new int[]{
                a[1] * b[2] - a[2] * b[1],
                a[2] * b[0] - a[0] * b[2],
                a[0] * b[1] - a[1] * b[0]
        };
    }

    static int[] neg(int[] a) {
        return new int[]{-a[0], -a[1], -a[2]};
    }

    static boolean eq(int[] a, int[] b) {
        return a[0] == b[0] && a[1] == b[1] && a[2] == b[2];
    }

    static boolean isZero(int[] a) {
        return a[0] == 0 && a[1] == 0 && a[2] == 0;
    }

    static int colorId(String s) {
        return s.hashCode();
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c != -1 && c <= ' ');
            while (c != -1 && c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        Integer nextIntNullable() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

