/*
We have n cubes, each with 6 face colors.
Need minimum repaint count so that all cubes become identical up to rotation.

Approach:
- Enumerate all 24 rotations of a cube.
- For each cube i, precompute its 24 rotated colorings.
- Choose one cube as reference (cube 0). In an optimal solution, the final target
  coloring can be assumed to be some rotation of cube 0's final orientation?
  More generally, brute force over all 24 orientations of cube 0 as target frame.
- For every other cube, choose the rotation minimizing mismatches against target.
- Sum mismatches; take minimum over 24 target orientations of cube 0.

Why valid:
Any target coloring T has some orientation relative to cube 0. Rotating the whole
configuration, T can be aligned with one of cube 0's 24 orientations, and mismatch
counts remain unchanged.

Input format:
Multiple datasets.
Each dataset starts with integer n. If n == 0, end.
Then n lines follow, each containing 6 strings/colors.

This is the standard format for this problem.
*/

// Face indices:
// 0 = up, 1 = down, 2 = front, 3 = back, 4 = left, 5 = right

array<int, 6> rotX(const array<int,6>& a) {
    // rotate around left-right axis: front->up->back->down->front
    return {a[2], a[3], a[1], a[0], a[4], a[5]};
}
array<int, 6> rotY(const array<int,6>& a) {
    // rotate around front-back axis: left->up->right->down->left
    return {a[4], a[5], a[2], a[3], a[1], a[0]};
}
array<int, 6> rotZ(const array<int,6>& a) {
    // rotate around up-down axis: front->right->back->left->front
    return {a[0], a[1], a[4], a[5], a[3], a[2]};
}

vector<array<int,6>> generate_rotations(const array<int,6>& start) {
    vector<array<int,6>> res;
    queue<array<int,6>> q;
    set<array<int,6>> vis;
    q.push(start);
    vis.insert(start);
    while (!q.empty()) {
        auto cur = q.front(); q.pop();
        res.push_back(cur);
        array<int,6> nxts[3] = {rotX(cur), rotY(cur), rotZ(cur)};
        for (auto &nxt : nxts) {
            if (!vis.count(nxt)) {
                vis.insert(nxt);
                q.push(nxt);
            }
        }
    }
    return res; // should be 24
}

