            for (int j = 0; j < 6; ++j) {
                if (!mp.count(cubes_str[i][j])) mp[cubes_str[i][j]] = cid++;
                cubes[i][j] = mp[cubes_str[i][j]];
            }
        }

        vector<vector<array<int,6>>> rots(n);
        for (int i = 0; i < n; ++i) {
            rots[i] = generate_rotations(cubes[i]);
        }

        int ans = INT_MAX;

        // Try every orientation of cube 0 as target
        for (const auto& target : rots[0]) {
            int total = 0;
            for (int i = 0; i < n; ++i) {
                int best = 6;
                for (const auto& r : rots[i]) {
                    int diff = 0;
                    for (int f = 0; f < 6; ++f)
                        if (r[f] != target[f]) ++diff;
                    best = min(best, diff);
                }
                total += best;
            }
            ans = min(ans, total);
        }

        cout << ans << '\n';
    }

    return 0;
}
